//! The parts of Laravel that sit on top of the encrypter, produced by the real Laravel classes
//! (`fixtures/app-vectors.json`, regenerated by `scripts/generate_app_vectors.php`): random
//! keys, encrypted cookies, encrypted session payloads and Eloquent encrypted casts.

use base64::engine::general_purpose::STANDARD;
use base64::Engine as _;
use laravel_rust_encryption::{Cipher, Encrypter, Error, Value};
use serde_json::Value as Json;

fn b64(s: &str) -> Vec<u8> {
    STANDARD.decode(s).expect("valid base64 in fixture")
}

fn fixtures() -> Json {
    let data = std::fs::read_to_string(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/fixtures/app-vectors.json"
    ))
    .expect("read fixtures/app-vectors.json");
    serde_json::from_str(&data).expect("parse fixtures/app-vectors.json")
}

fn group<'a>(fx: &'a Json, name: &str) -> &'a Vec<Json> {
    let list = fx[name]
        .as_array()
        .unwrap_or_else(|| panic!("missing {name}"));
    assert!(!list.is_empty(), "{name} is empty");
    list
}

fn cipher_of(v: &Json) -> Cipher {
    v["cipher"].as_str().unwrap().parse().unwrap()
}

fn key(fx: &Json, field: &str, cipher: Cipher) -> Vec<u8> {
    b64(fx[field].as_str().unwrap())[..cipher.key_size()].to_vec()
}

fn encrypter(fx: &Json, cipher: Cipher) -> Encrypter {
    Encrypter::new(&key(fx, "key_b64", cipher), cipher).unwrap()
}

/// The encrypter of an application that rotated from the previous key to the current one.
fn rotated(fx: &Json, cipher: Cipher) -> Encrypter {
    encrypter(fx, cipher)
        .with_previous_keys([key(fx, "previous_key_b64", cipher)])
        .unwrap()
}

#[test]
fn random_keys_work_with_every_cipher() {
    let fx = fixtures();
    let vectors = group(&fx, "random_keys");
    assert!(vectors.len() >= 96);
    for v in vectors {
        let cipher = cipher_of(v);
        let enc = Encrypter::new(&b64(v["key_b64"].as_str().unwrap()), cipher).unwrap();
        let want = b64(v["plaintext_b64"].as_str().unwrap());
        assert_eq!(
            enc.decrypt_bytes(v["payload"].as_str().unwrap()).unwrap(),
            want,
            "{}",
            v["name"]
        );
    }
}

#[test]
fn laravel_cookies_decrypt_and_validate() {
    let fx = fixtures();
    for v in group(&fx, "cookies") {
        let cipher = cipher_of(v);
        let name = v["cookie_name"].as_str().unwrap();
        let want = String::from_utf8(b64(v["value_b64"].as_str().unwrap())).unwrap();
        let payload = v["payload"].as_str().unwrap();

        match v["key"].as_str().unwrap() {
            "current" => {
                assert_eq!(
                    encrypter(&fx, cipher)
                        .decrypt_cookie(name, payload)
                        .unwrap(),
                    want
                );
                assert_eq!(
                    rotated(&fx, cipher).decrypt_cookie(name, payload).unwrap(),
                    want
                );
            }
            // Issued before the key was rotated: only an encrypter that knows the old key can
            // read it (the prefix is bound to the key it was issued with).
            "previous" => {
                assert!(encrypter(&fx, cipher)
                    .decrypt_cookie(name, payload)
                    .is_err());
                assert_eq!(
                    rotated(&fx, cipher).decrypt_cookie(name, payload).unwrap(),
                    want
                );
            }
            other => panic!("unknown key {other}"),
        }
    }
}

#[test]
fn a_cookie_is_bound_to_its_name() {
    let fx = fixtures();
    let v = group(&fx, "cookies")
        .iter()
        .find(|v| v["cookie_name"] == "laravel_session" && v["key"] == "current")
        .unwrap();
    let enc = encrypter(&fx, cipher_of(v));
    let payload = v["payload"].as_str().unwrap();
    assert!(enc.decrypt_cookie("laravel_session", payload).is_ok());
    assert_eq!(
        enc.decrypt_cookie("XSRF-TOKEN", payload),
        Err(Error::InvalidCookie)
    );
    // A payload from encryptString has no prefix at all.
    let plain = enc.encrypt_string("no prefix here").unwrap();
    assert_eq!(
        enc.decrypt_cookie("laravel_session", &plain),
        Err(Error::InvalidCookie)
    );
    // Neither does one shorter than the prefix.
    let short = enc.encrypt_string("short").unwrap();
    assert_eq!(
        enc.decrypt_cookie("laravel_session", &short),
        Err(Error::InvalidCookie)
    );
}

#[test]
fn cookies_round_trip_and_use_laravels_layout() {
    for cipher in [
        Cipher::Aes128Cbc,
        Cipher::Aes256Cbc,
        Cipher::Aes128Gcm,
        Cipher::Aes256Gcm,
    ] {
        let enc = Encrypter::new(&vec![0x2b; cipher.key_size()], cipher).unwrap();
        for (name, value) in [
            ("laravel_session", "abc123"),
            ("empty", ""),
            ("pipes", "a|b|c"),
            ("küche", "Grüße 世界"),
        ] {
            let payload = enc.encrypt_cookie(name, value).unwrap();
            assert_eq!(enc.decrypt_cookie(name, &payload).unwrap(), value);

            // The plaintext is a 41-byte prefix (40 hex characters and "|") plus the value.
            let plain = enc.decrypt_string(&payload).unwrap();
            assert_eq!(plain.len(), 41 + value.len());
            assert_eq!(plain.as_bytes()[40], b'|');
            assert!(plain[..40]
                .bytes()
                .all(|b| b.is_ascii_hexdigit() && !b.is_ascii_uppercase()));
            assert!(plain.ends_with(value));
        }
    }
}

#[test]
fn the_cookie_prefix_matches_laravels() {
    // PHP: hash_hmac('sha1', 'laravel_session' . 'v2', str_repeat("\x2b", 32)) . '|'
    let enc = Encrypter::new(&[0x2b; 32], Cipher::Aes256Cbc).unwrap();
    let plain = enc
        .decrypt_string(&enc.encrypt_cookie("laravel_session", "x").unwrap())
        .unwrap();
    assert_eq!(&plain[..40], "de34b8b683dec375f8d5c86fc41645c59842c10e");
}

#[test]
fn eloquent_encrypted_casts_decrypt() {
    let fx = fixtures();
    let casts = group(&fx, "casts");
    assert!(casts.len() >= 16);
    for v in casts {
        let enc = encrypter(&fx, cipher_of(v));
        let want = String::from_utf8(b64(v["plaintext_b64"].as_str().unwrap())).unwrap();
        // A cast is Crypt::encryptString() of the value, or of its JSON.
        assert_eq!(
            enc.decrypt_string(v["payload"].as_str().unwrap()).unwrap(),
            want,
            "{}",
            v["name"]
        );
    }

    // The JSON casts hold JSON, which any JSON library reads.
    let v = casts
        .iter()
        .find(|v| v["name"] == "aes-256-cbc/list")
        .unwrap();
    let json: Json = serde_json::from_str(
        &encrypter(&fx, Cipher::Aes256Cbc)
            .decrypt_string(v["payload"].as_str().unwrap())
            .unwrap(),
    )
    .unwrap();
    assert_eq!(json["y"], serde_json::json!([1, 2]));
    assert_eq!(json["z"], "ü");
}

#[test]
fn encrypted_sessions_decrypt_to_the_serialized_attributes() {
    let fx = fixtures();
    let sessions = group(&fx, "sessions");
    assert!(sessions.iter().any(|v| v["serialization"] == "php"));

    for v in sessions {
        let enc = encrypter(&fx, cipher_of(v));
        let payload = v["payload"].as_str().unwrap();
        let inner = b64(v["inner_b64"].as_str().unwrap());

        // session.encrypt stores Crypt::encrypt() of the already serialized attributes, so the
        // value Laravel decrypts to is a string holding the PHP (or JSON) serialization.
        let Value::String(text) = enc.decrypt(payload).unwrap() else {
            panic!("{}: the payload does not decrypt to a string", v["name"])
        };
        assert_eq!(text.as_bytes(), inner.as_slice(), "{}", v["name"]);

        match v["serialization"].as_str().unwrap() {
            "php" => {
                let attributes = Value::from_php_serialized(&text).unwrap();
                assert_eq!(attributes.get("user_id"), Some(&Value::Int(7)));
                assert_eq!(
                    attributes.get("name").and_then(Value::as_str),
                    Some("Grüße")
                );
                assert_eq!(
                    attributes.get("cart").and_then(|c| c.get("apple")),
                    Some(&Value::Int(2))
                );
                assert_eq!(
                    attributes.get("_token").and_then(Value::as_str),
                    v["token"].as_str()
                );
                // ...and writes back what Laravel reads.
                let again = Value::from_php_serialized(attributes.to_php_serialized().unwrap());
                assert_eq!(again, Ok(attributes));
            }
            "json" => {
                let attributes: Json = serde_json::from_str(&text).unwrap();
                assert_eq!(attributes["user_id"], 7);
                assert_eq!(attributes["_token"], v["token"]);
            }
            other => panic!("unknown serialization {other}"),
        }
    }
}
